        return json.dumps(text)
    if not isinstance(node, list):
        raise TypeError(
            "%s 必须是嵌套 list，得到 %s" % (name, type(node).__name__)
        )
    return "[" + ",".join(
        _dump_hex_tensor(child, depth - 1, name) for child in node
    ) + "]"

